(19, '5', 'Drive gear lubrication ', 'Lubricate with lubriplate gear shield extra heavy manufactered by Dow corning or equivalent. Gears should be lubricated at maximum intervals of one month or more often as required.', '4'),
(20, '5', 'Drive belt condition', 'Check the condition of the belt and replace it if required.', '4'),
(21, '6', 'HAPA Filter Inspection', 'ok', '3'),
(22, '7', 'external calibration', 'ok', '2');
