INSERT INTO `packing_ebmr_master` (`id`, `plant_id`, `product_code`, `product_name`, `master_json`, `revision`, `updated_at`, `updated_by_emp_id`) VALUES
(1, '142', '123', 'Magaldrate IP/BP/USP/Ph Eur', '{\"Stages\":[{\"stages\":\"1. Batch documentation & release to packing\",\"Steps\":[{\"id\":\"1\",\"step\":\"Verify BPR \\/ packing order vs ERP â€” product, batch, quantity\",\"Substeps\":[]},{\"id\":\"2\",\"step\":\"Confirm artwork \\/ label reference (approved code, revision, language)\",\"Substeps\":[]},{\"id\":\"3\",\"step\":\"Check prior batch clearance on line \\/ area log\",\"Substeps\":[{\"id\":\"1\",\"substep\":\"Sign line clearance checklist\"},{\"id\":\"2\",\"substep\":\"Record previous product & batch on log\"}]}]},{\"stages\":\"2. Material staging â€” excipients, bulk, primary & secondary PM\",\"Steps\":[{\"id\":\"4\",\"step\":\"Issue and verify excipients \\/ bulk against BPR (quantity, AR numbers, retest status)\",\"Substeps\":[{\"id\":\"1\",\"substep\":\"Weighing area: dual verification of labels\"},{\"id\":\"2\",\"substep\":\"Quarantine release reference \\/ COA available\"}]},{\"id\":\"5\",\"step\":\"Primary packaging materials (containers, closures, foils) â€” issuance vs BPR\",\"Substeps\":[]},{\"id\":\"6\",\"step\":\"Secondary materials (cartons, leaflets, shipper) â€” issuance vs BPR\",\"Substeps\":[]}]},{\"stages\":\"3. Primary packing\",\"Steps\":[{\"id\":\"7\",\"step\":\"Set up dosing \\/ filling \\/ sealing per validated parameters\",\"Substeps\":[]},{\"id\":\"8\",\"step\":\"In-process checks: fill weight \\/ count, seal integrity sample\",\"Substeps\":[]},{\"id\":\"9\",\"step\":\"Reject \\/ rework segregation procedure if applicable\",\"Substeps\":[]}]},{\"stages\":\"4. Serialization, coding & aggregation (if applicable)\",\"Steps\":[{\"id\":\"10\",\"step\":\"Line setup for serial codes \\/ 2D printing â€” verify sample print\",\"Substeps\":[]},{\"id\":\"11\",\"step\":\"Aggregation to bundle \\/ case â€” scan verification\",\"Substeps\":[]},{\"id\":\"12\",\"step\":\"Reject handling for code failures\",\"Substeps\":[]}]},{\"stages\":\"5. Secondary packing & finished presentation\",\"Steps\":[{\"id\":\"13\",\"step\":\"Cartoning \\/ labelling â€” match artwork proof\",\"Substeps\":[]},{\"id\":\"14\",\"step\":\"Manual pack steps (leaflet, desiccant, bundle)\",\"Substeps\":[]}]},{\"stages\":\"6. Line clearance after packing & area hygiene\",\"Steps\":[{\"id\":\"15\",\"step\":\"Post-batch line clearance â€” remove residue, verify counts\",\"Substeps\":[{\"id\":\"1\",\"substep\":\"Sign equipment usage \\/ cleaning log if required\"}]}]},{\"stages\":\"7. QA control, hold & release to FG store\",\"Steps\":[{\"id\":\"16\",\"step\":\"Finished goods transfer to quarantine \\/ sampled as per plan\",\"Substeps\":[]},{\"id\":\"17\",\"step\":\"Batch documentation completeness check for packing section\",\"Substeps\":[]}]}]}', 1, '2026-03-26 12:47:52', 'Cyclone');
