INSERT INTO `question_master_hdr` (`id`, `plant_id`, `department_name`, `training_category`, `subject`, `questinner_heading`, `evaluator_name`, `total_marks`, `duration`, `questions`) VALUES
(1, '142', 'Human Resource', 'Level 1 ( Read a Document )', 'induction training', 'sop reviewing', 'Prasad Barhate', '10', '30', '[{\"question\":\"SOP READING AND ANALYSIS\",\"option1\":\"YES\",\"option2\":\"NO\",\"option3\":\"OK\",\"option4\":\"NONE OF THE ABOVE\",\"answer\":\"Option 1\"}]'),
(2, '142', 'FOR ALL', 'Level 2 ( Attend a Training/Information Seminar )', 'FIRE EMERGENCY ', 'SANKET ', 'TEJAS ', '10', '5', '[{\"question\":\"WHERE THE EMPLOYEES SHOULD GATHER IN FIRE EMERGENCY \",\"option1\":\"OFFICE\",\"option2\":\"SECOND FLOOR \",\"option3\":\"STORE ROOM\",\"option4\":\"ASSEMBLY POINT \",\"answer\":\"Option 4\"}]'),
(3, '142', 'Human Resource', 'Level 1 ( Read a Document )', 'Employee Code of Conduct', 'HR Basic Policy Understanding Test', 'Samiskha Vivek', '10', '30', '[{\"question\":\"What is the main purpose of the Employee Code of Conduct?\",\"option1\":\"To guide employee behavior at work\",\"option2\":\"To increase salary\",\"option3\":\"To reduce working hours\",\"option4\":\"To control marketing activities\",\"answer\":\"Option 1\"}]'),
(4, '142', 'FOR ALL', 'Level 3 ( On The Job Training )', 'Safe Handling and Administration of Pharmaceutical Ampules', 'Ampule Handling and Safety Assessment', 'QA Manager', '10', '', '[{\"question\":\"What is the primary purpose of an ampule?\",\"option1\":\"Storage of solid drugs\",\"option2\":\"Storage of sterile liquid medications\",\"option3\":\"Mixing chemicals\",\"option4\":\"Measuring dosage\",\"answer\":\"Option 2\"},{\"question\":\"Ampules are usually made of which material?\",\"option1\":\"Plastic only\",\"option2\":\"Rubber\",\"option3\":\"Glass\",\"option4\":\"Metal\",\"answer\":\"Option 3\"},{\"question\":\"What should be done before opening an ampule?\",\"option1\":\"Shake vigorously\",\"option2\":\"Heat it\",\"option3\":\"Tap to bring liquid down from the neck\",\"option4\":\"Freeze it\",\"answer\":\"Option 3\"},{\"question\":\"How is an ampule typically opened?\",\"option1\":\"Cutting with scissors\",\"option2\":\"Twisting the cap\",\"option3\":\"Snapping the neck\",\"option4\":\"Pulling the top\",\"answer\":\"Option 3\"},{\"question\":\"Why is a filter needle used while withdrawing liquid from an ampule?\",\"option1\":\"To increase speed\",\"option2\":\"To reduce drug potency\",\"option3\":\"To prevent glass particles from entering the syringe\",\"option4\":\"To change color of drug\",\"answer\":\"Option 3\"}]'),
(5, '142', 'Quality Assurance', 'Level 1 ( Read a Document )', 'Training Questionnaire Master for QA Training Session', 'Quality Assurance Training Assessment Questionnaire.', 'Piyusha Shinde', '100', '30', '[{\"question\":\"What does GMP stand for?\",\"option1\":\"Good Manufacturing Practice\",\"option2\":\"General Manufacturing Process\",\"option3\":\"Global Manufacturing Policy\",\"option4\":\"Good Material Practice\",\"answer\":\"Option 1\"},{\"question\":\"What is ALCOA+ related to?\",\"option1\":\"Equipment qualification\",\"option2\":\"Data Integrity\",\"option3\":\"Sampling method\",\"option4\":\"Cleaning validation\",\"answer\":\"Option 2\"},{\"question\":\"Which document is used for manufacturing records?\",\"option1\":\"SOP\",\"option2\":\"BMR/BPR\",\"option3\":\"COA\",\"option4\":\"STP\",\"answer\":\"Option 2\"},{\"question\":\"What is the purpose of CAPA?\",\"option1\":\"To record deviation\",\"option2\":\"To correct and prevent issues\",\"option3\":\"To audit documents\",\"option4\":\"To test products\",\"answer\":\"Option 2\"}]'),
(6, '142', 'Quality Control', 'Level 1 ( Read a Document )', 'Good Laboratory Practices ', 'GLP Basic Awareness â€“ Level 1', 'Dr. Anil Sharma', '10', '30', '[{\"question\":\"What does GLP stand for\",\"option1\":\"Good Lab Practice\",\"option2\":\"Good Laboratory Practice\",\"option3\":\"General Lab Procedure\",\"option4\":\"Global Lab Practice\",\"answer\":\"Option 1\"}]'),
(7, '142', 'Quality Assurance', 'Level 2 ( Attend a Training/Information Seminar )', 'QA Level 2 Training Assessment Questionnaire â€“ Seminar Evaluation', 'Level 2 QA Training Effectiveness Assessment Questionnaire', 'Piyusha Shinde', '10', '20', '[{\"question\":\"Which of the following is part of ALCOA+?\",\"option1\":\"Traceable\",\"option2\":\"Attributable\",\"option3\":\"Transferable\",\"option4\":\"Testable\",\"answer\":\"Option 2\"},{\"question\":\"Which is the primary objective of CAPA?\",\"option1\":\"Record deviation\",\"option2\":\"Identify root cause and prevent recurrence\",\"option3\":\"Audit process\",\"option4\":\"Perform testing\",\"answer\":\"Option 2\"},{\"question\":\"Which tool is most suitable for identifying multiple causes?SOP\",\"option1\":\"SOP\",\"option2\":\"Checklist\",\"option3\":\"Fishbone Diagram\",\"option4\":\"Logbook\",\"answer\":\"Option 3\"},{\"question\":\"What is the first step in Quality Risk Management?\",\"option1\":\"Risk control\",\"option2\":\"Risk review\",\"option3\":\"Risk identification\",\"option4\":\"Risk reduction\",\"answer\":\"Option 3\"}]'),
(8, '142', 'Quality Assurance', 'Level 3 ( On The Job Training )', 'OJT Program for QA â€“ Practical Training & Assessment', 'On-the-Job Training (OJT) â€“ QA Competency Assessment Questionnaire', 'Piyusha Shinde', '10', '20', '[{\"question\":\"What is the first step before starting any manufacturing activity?\",\"option1\":\"Start equipment\",\"option2\":\"Line clearance\",\"option3\":\"Documentation\",\"option4\":\"Sampling\",\"answer\":\"Option 2\"},{\"question\":\"Which document is verified during OJT in production?\",\"option1\":\"COA\",\"option2\":\"BMR/BPR\",\"option3\":\"SOP only\",\"option4\":\"Invoice\",\"answer\":\"Option 2\"},{\"question\":\"What is the purpose of in-process checks?\",\"option1\":\"Record keeping\",\"option2\":\"Monitor product quality during process\",\"option3\":\"Audit requirement\",\"option4\":\"Documentation\",\"answer\":\"Option 2\"},{\"question\":\"Which is part of data integrity?\",\"option1\":\"Editable records\",\"option2\":\"ALCOA+ principles\",\"option3\":\"Verbal communication\",\"option4\":\"Draft records\",\"answer\":\"Option 3\"}]');
