DELIMITER $$
CREATE TRIGGER `batch_planning_no_insert` BEFORE INSERT ON `batch_planning` FOR EACH ROW BEGIN

SET @lastID = (SELECT id FROM batch_planning ORDER BY id DESC LIMIT 1);
