--
-- Triggers `bmr_packing`
--
DELIMITER $$
CREATE TRIGGER `bmr_packing_no_insert` BEFORE INSERT ON `bmr_packing` FOR EACH ROW BEGIN
    DECLARE lastID INT DEFAULT 0;
    SELECT IFNULL(MAX(id), 0) INTO lastID FROM bmr_packing;
    SET lastID = lastID + 1;
    SET NEW.packing_no = CONCAT('BP', LPAD(CONVERT(lastID, CHAR), 4, '0'));
END
$$
DELIMITER ;

