--
-- Triggers `challan`
--
DELIMITER $$
CREATE TRIGGER `ch_no` BEFORE INSERT ON `challan` FOR EACH ROW BEGIN
    DECLARE lastID INT DEFAULT 0;
    SELECT IFNULL(MAX(id), 0) INTO lastID FROM challan;
    SET lastID = lastID + 1;
    SET NEW.challan_no = CONCAT('CH-', LPAD(CONVERT(lastID, CHAR), 3, '0'));
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `inward_no` BEFORE INSERT ON `challan` FOR EACH ROW BEGIN
    DECLARE lastID INT DEFAULT 0;
    SELECT IFNULL(MAX(id), 0) INTO lastID FROM challan;
    SET lastID = lastID + 1;
    SET NEW.inward_no = CONCAT('IN-', LPAD(CONVERT(lastID, CHAR), 3, '0'));
END
$$
DELIMITER ;

