DELIMITER $$
CREATE TRIGGER `dayStoreCode` BEFORE INSERT ON `daystoremaster` FOR EACH ROW BEGIN
    DECLARE lastID INT DEFAULT 0;
    SELECT IFNULL(MAX(id), 0) INTO lastID FROM dayStoreMaster;
    SET lastID = lastID + 1;
    SET NEW.dayStoreCode = CONCAT('DS', LPAD(CONVERT(lastID, CHAR), 3, '0'));
END
$$
DELIMITER ;

