--
-- Triggers `enquiry`
--
DELIMITER $$
CREATE TRIGGER `enquiry_no` BEFORE INSERT ON `enquiry` FOR EACH ROW BEGIN
    DECLARE lastID INT DEFAULT 0;
    SELECT IFNULL(MAX(id), 0) INTO lastID FROM enquiry;
    SET lastID = lastID + 1;
    SET NEW.enquiry_no = CONCAT('ENQ', LPAD(lastID, 2, '0'));
END
$$
DELIMITER ;

