DELIMITER $$
CREATE TRIGGER `label_no_insert` BEFORE INSERT ON `label` FOR EACH ROW BEGIN
    DECLARE lastID INT DEFAULT 0;
    SELECT IFNULL(MAX(id), 0) INTO lastID FROM label;
