--
-- Triggers `po_entry`
--
DELIMITER $$
CREATE TRIGGER `client_order_no_insert` BEFORE INSERT ON `po_entry` FOR EACH ROW BEGIN

SET @lastID = (SELECT id FROM po_entry ORDER BY id DESC LIMIT 1);
IF @lastID IS NULL OR @lastID = '' THEN
    SET @lastID = 0;
END IF;
SET @lastID = @lastID +1;
SET NEW.order_no = concat('O1', LPAD(CONVERT(@lastID, CHAR), 6, '0'));
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `epo_no` BEFORE INSERT ON `po_entry` FOR EACH ROW BEGIN

SET @lastID = (SELECT id FROM po_entry ORDER BY id DESC LIMIT 1);
IF @lastID IS NULL OR @lastID = '' THEN
    SET @lastID = 0;
END IF;
SET @lastID = @lastID +1;
SET NEW.epo_no = concat('EPO-', LPAD(CONVERT(@lastID, CHAR), 3, '0'));
END
$$
DELIMITER ;

