--
-- Triggers `p_changecontrol`
--
DELIMITER $$
CREATE TRIGGER `ChnageControlNo` BEFORE INSERT ON `p_changecontrol` FOR EACH ROW BEGIN
    DECLARE lastSr INT DEFAULT 0;
    DECLARE currentYear CHAR(2);
    DECLARE lastchangeControl_no VARCHAR(20);

    SET currentYear = RIGHT(YEAR(CURDATE()), 2);

    SELECT changeControl_no 
    INTO lastchangeControl_no
    FROM p_changeControl
    WHERE changeControl_no LIKE CONCAT('CC/', currentYear, '/%')
    ORDER BY id DESC
    LIMIT 1;

    IF lastchangeControl_no IS NOT NULL THEN
        SET lastSr = CAST(SUBSTRING_INDEX(lastchangeControl_no, '/', -1) AS UNSIGNED);
    ELSE
        SET lastSr = 0;
    END IF;

    SET lastSr = lastSr + 1;
    SET NEW.changeControl_no = CONCAT('CC/', currentYear, '/', LPAD(lastSr, 3, '0'));
END
$$
DELIMITER ;

