--
-- Triggers `tax_invoice`
--
DELIMITER $$
CREATE TRIGGER `invoice` BEFORE INSERT ON `tax_invoice` FOR EACH ROW BEGIN
    DECLARE lastID INT DEFAULT 0;
    SELECT IFNULL(MAX(id), 0) INTO lastID FROM tax_invoice;
    SET lastID = lastID + 1;
    SET NEW.invoice_no = CONCAT('IN-', LPAD(CONVERT(lastID, CHAR), 4, '0'));
END
$$
DELIMITER ;

