DELIMITER $$
CREATE TRIGGER `trg_generate_test_method_no` BEFORE INSERT ON `test` FOR EACH ROW BEGIN
    DECLARE last_no INT DEFAULT 0;
    DECLARE new_no VARCHAR(20);
    SELECT CAST(SUBSTRING(software_test_method_no, 4) AS UNSIGNED)
    INTO last_no
    FROM test
    WHERE software_test_method_no LIKE 'STM%'
    ORDER BY id DESC
    LIMIT 1;
    SET last_no = IFNULL(last_no, 0) + 1;
    SET new_no = CONCAT('STM', LPAD(last_no, 4, '0'));
    SET NEW.software_test_method_no = new_no;
END
$$
DELIMITER ;

