--
-- Triggers `voucherentry`
--
DELIMITER $$
CREATE TRIGGER `voucherNumber1` BEFORE INSERT ON `voucherentry` FOR EACH ROW BEGIN
    DECLARE lastID INT DEFAULT 0;
    SELECT IFNULL(MAX(id), 0) INTO lastID FROM voucherentry;
    SET lastID = lastID + 1;
    SET NEW.voucher_no = CONCAT('VE-', LPAD(CONVERT(lastID, CHAR), 3, '0'));
END
$$
DELIMITER ;

