--
-- Dumping data for table `work_order_materials`
--


--
-- Triggers `work_order_materials`
--
DELIMITER $$
CREATE TRIGGER `workorderno` BEFORE INSERT ON `work_order_materials` FOR EACH ROW BEGIN
    DECLARE next_id INT;

    -- Get the maximum numeric part of Fo_code and increment it
    SELECT IFNULL(MAX(CAST(SUBSTRING(workorder_no, 3) AS UNSIGNED)), 0) + 1
    INTO next_id
    FROM Work_order_materials;

    -- Generate the new Fo_code like FO001, FO002, FO003
    SET NEW.workorder_no = CONCAT('BO', LPAD(next_id, 3, '0'));
END
$$
DELIMITER ;

